// Minimal QRCode library for admin panel
// This is a simplified version to avoid CDN blocking issues

window.QRCode = {
    toCanvas: function(canvas, text, options, callback) {
        console.log('QRCode.toCanvas called with:', text);
        // Simple fallback - just show the text
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#000';
        ctx.font = '12px Arial';
        ctx.fillText('QR: ' + text, 10, 20);
        if (callback) callback(null);
    },
    
    toString: function(text, options, callback) {
        console.log('QRCode.toString called with:', text);
        if (callback) callback(null, 'QR: ' + text);
    }
};
